// llmenv hook bridge for opencode 2.x. Generated by llmenv; do not edit.
//
// The hook table is `llmenv-hooks.json` beside this file. Each hook gets the
// payload that Claude Code would send: a Claude tool name, Claude argument
// keys, and the session id of the call. A hook blocks a tool call by exit
// code 2 or by a `permissionDecision` of "deny" on stdout.
import { readFileSync } from "node:fs";
import { spawn } from "node:child_process";

const TABLE_URL = new URL("./llmenv-hooks.json", import.meta.url);
const DEFAULT_TIMEOUT_MS = 30000;

/** Why the hook table did not load, or null. Every hook is off then, so each request says so. */
let tableError = null;

const EMPTY_TABLE = { hooks: [], tools: {}, mcpServers: {} };

/** A table is usable when every hook names an event and a command, and the maps are objects. */
function isTableShape(table) {
  const plainObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  return (
    plainObject(table) &&
    Array.isArray(table.hooks) &&
    table.hooks.every((h) => plainObject(h) && typeof h.event === "string" && typeof h.command === "string") &&
    plainObject(table.tools) &&
    (table.mcpServers === undefined || plainObject(table.mcpServers))
  );
}

function loadTable() {
  let table;
  try {
    table = JSON.parse(readFileSync(TABLE_URL, "utf8"));
  } catch (e) {
    tableError = `llmenv: no llmenv hook runs in this opencode session, because ${TABLE_URL.pathname} cannot be read: ${e.message}. Fix: run \`llmenv materialize\`.`;
    console.error(tableError);
    return EMPTY_TABLE;
  }
  // A file that parses but has the wrong shape would fail later, on each tool call. Reject it here.
  if (!isTableShape(table)) {
    tableError = `llmenv: no llmenv hook runs in this opencode session, because ${TABLE_URL.pathname} does not have the hook table shape. Fix: run \`llmenv materialize\`.`;
    console.error(tableError);
    return EMPTY_TABLE;
  }
  return table;
}

/** Record a hook error and log it where it occurs, so a session that ends first does not lose it. */
function reportError(out, text) {
  console.error(text);
  out.errors.push(text);
}

/** Queue a hook result for the next request. A block is also logged now, in case the session ends first. */
function queueOutcome(s, out) {
  if (out.block) console.error(out.block);
  s.errors.push(...out.errors, ...(out.block ? [out.block] : []));
}

const TABLE = loadTable();

/** The MCP namespaces, longest first, so a server `a_b` is not read as server `a`. */
const NAMESPACES = Object.entries(TABLE.mcpServers ?? {}).sort(([a], [b]) => b.length - a.length);

/** The project folder of the opencode instance, from the plugin context. */
let workDir = process.cwd();

/** The neutral tool name and Claude argument keys for an opencode tool call. */
export function toNeutral(tool, input) {
  const mapped = Object.hasOwn(TABLE.tools, tool) ? TABLE.tools[tool] : undefined;
  if (mapped) return { name: mapped.name, input: renameKeys(input, mapped.args) };
  for (const [namespace, server] of NAMESPACES) {
    const prefix = `${namespace}_`;
    if (tool.startsWith(prefix)) {
      return { name: `mcp__${server}__${tool.slice(prefix.length)}`, input };
    }
  }
  return { name: tool, input };
}

/** `input` with the opencode keys put back, for an `updatedInput` from a hook. */
export function fromNeutral(tool, input) {
  const mapped = Object.hasOwn(TABLE.tools, tool) ? TABLE.tools[tool] : undefined;
  if (!mapped) return input;
  const back = Object.fromEntries(Object.entries(mapped.args).map(([from, to]) => [to, from]));
  return renameKeys(input, back);
}

function renameKeys(input, renames) {
  if (input === null || typeof input !== "object" || Array.isArray(input)) return input;
  return Object.fromEntries(Object.entries(input).map(([k, v]) => [renames[k] ?? k, v]));
}

/** Whether a Claude-style matcher selects `toolName`. No matcher, "", and "*" select every tool. */
export function matches(matcher, toolName) {
  if (matcher === undefined || matcher === null || matcher === "" || matcher === "*") return true;
  return new RegExp(`^(?:${matcher})$`).test(toolName);
}

/**
 * Run every hook of `event` that selects `toolName`. Returns the joined
 * `additionalContext`, a block decision, an `updatedInput`, and the errors of
 * hooks that could not run.
 */
export async function runHooks(event, sessionID, extra, toolName) {
  const out = { context: [], errors: [], block: null, updatedInput: null };
  let current = extra;
  for (const hook of TABLE.hooks) {
    if (hook.event !== event) continue;
    if (toolName !== undefined) {
      try {
        if (!matches(hook.matcher, toolName)) continue;
      } catch (e) {
        const why = `llmenv: the matcher ${JSON.stringify(hook.matcher)} of a ${event} hook is not a valid pattern: ${e.message}`;
        // A gate with a broken matcher cannot tell which calls it guards, so it blocks them all.
        if (hook.failClosed) {
          out.block = why;
          return out;
        }
        reportError(out, why);
        continue;
      }
    }
    const payload = {
      hook_event_name: event,
      session_id: sessionID ?? "",
      cwd: workDir,
      ...current,
    };
    let result;
    try {
      result = await spawnHook(hook.command, hook.timeout ?? DEFAULT_TIMEOUT_MS, payload);
    } catch (e) {
      const why = `llmenv: the ${event} hook \`${hook.command}\` could not run: ${e.message}`;
      // A gate that cannot run must not let the call through.
      if (hook.failClosed) {
        out.block = why;
        return out;
      }
      reportError(out, why);
      continue;
    }
    if (hook.failClosed && result.timedOut) {
      out.block = `llmenv: the ${event} hook \`${hook.command}\` timed out, so the call is blocked. Run it again, or run \`llmenv doctor\`.`;
      return out;
    }
    // A gate passes a call only on exit 0 (allow) or exit 2 (deny). Any other exit, such as 1 or
    // 127 for a missing program, and a signal kill, must not let the call through.
    if (hook.failClosed && result.code !== 0 && result.code !== 2) {
      const how = result.code === null ? "was killed by a signal" : `exited with ${result.code}`;
      const detail = result.stderr ? `: ${result.stderr}` : "";
      out.block = `llmenv: the ${event} hook \`${hook.command}\` ${how}, so the call is blocked${detail}`;
      return out;
    }
    const before = out.updatedInput;
    readResult(event, hook.command, result, out);
    if (out.block) return out;
    // A later hook checks the input that the tool will get, not the input before a rewrite.
    if (out.updatedInput !== before) current = { ...current, tool_input: out.updatedInput };
  }
  return out;
}

function readResult(event, command, result, out) {
  if (result.timedOut) {
    reportError(out, `llmenv: the ${event} hook \`${command}\` timed out and was stopped`);
    return;
  }
  if (result.code === 2) {
    out.block = result.stderr || `Blocked by the llmenv hook \`${command}\``;
    return;
  }
  if (result.code !== 0) {
    const detail = result.stderr ? `: ${result.stderr}` : "";
    reportError(out, `llmenv: the ${event} hook \`${command}\` exited with ${result.code}${detail}`);
  }
  if (!result.stdout) return;
  let parsed;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    out.context.push(result.stdout);
    return;
  }
  const specific = parsed?.hookSpecificOutput ?? {};
  if (specific.permissionDecision === "deny") {
    out.block = specific.permissionDecisionReason || `Blocked by the llmenv hook \`${command}\``;
    return;
  }
  if (specific.updatedInput && typeof specific.updatedInput === "object") out.updatedInput = specific.updatedInput;
  if (typeof specific.additionalContext === "string" && specific.additionalContext.trim()) {
    out.context.push(specific.additionalContext);
  }
}

function spawnHook(command, timeoutMs, payload) {
  return new Promise((resolve, reject) => {
    // An absolute shell: a bare `sh` is looked up in PATH, which can name the project folder.
    // The hook leads its own process group, so a timeout stops its children too.
    const child = spawn("/bin/sh", ["-c", command], { stdio: ["pipe", "pipe", "pipe"], detached: true });
    let stdout = "";
    let stderr = "";
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };
    const timer = setTimeout(() => {
      try {
        process.kill(-child.pid, "SIGKILL");
      } catch {
        child.kill("SIGKILL");
      }
      // A child that holds the pipes open would keep `close` from firing, so the timer ends the wait.
      finish({ code: null, timedOut: true, stdout: stdout.trim(), stderr: stderr.trim() });
    }, timeoutMs);
    child.on("error", (e) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      reject(e);
    });
    child.stdout.on("data", (d) => (stdout += d.toString()));
    child.stderr.on("data", (d) => (stderr += d.toString()));
    child.on("close", (code) => finish({ code, timedOut: false, stdout: stdout.trim(), stderr: stderr.trim() }));
    // A hook that does not read stdin closes the pipe; that is not an error.
    child.stdin.on("error", () => {});
    child.stdin.end(JSON.stringify(payload));
  });
}

/** Per-session state: the SessionStart text, the current turn text, and errors to report. */
const sessions = new Map();

function state(sessionID) {
  let s = sessions.get(sessionID);
  if (!s) {
    s = { started: null, start: [], turn: [], once: [], errors: [], ended: false };
    sessions.set(sessionID, s);
  }
  return s;
}

function startSession(sessionID) {
  const s = state(sessionID);
  if (!s.started) {
    s.started = runHooks("SessionStart", sessionID, { source: "startup" })
      .then((out) => {
        s.start = out.context;
        queueOutcome(s, out);
      })
      .catch((e) => {
        // The chain must not reject, or each later tool call would throw a raw error with no fix.
        const text = `llmenv: the SessionStart hooks could not run: ${e?.message ?? e}. Fix: run \`llmenv doctor\`.`;
        console.error(text);
        s.errors.push(text);
      });
  }
  return s.started;
}

async function endSession(sessionID) {
  const s = sessions.get(sessionID);
  if (!s || s.ended) return;
  s.ended = true;
  const out = await runHooks("SessionEnd", sessionID, {});
  // The session is over, so no request can carry the texts still queued. Log those now, with the
  // SessionEnd hook's own context and errors. None of them has a request left to reach (#3037).
  // The errors queued earlier were logged where they occurred, so they are not logged again.
  for (const text of [
    ...out.context,
    ...(out.block ? [out.block] : []),
    ...out.errors,
    ...s.once,
  ]) {
    console.error(text);
  }
  sessions.delete(sessionID);
}

/**
 * The system parts for the next request: SessionStart text, turn text, the text of the last Stop
 * hooks, and hook errors. A table that did not load is named on every request.
 */
export function systemParts(sessionID) {
  const s = sessions.get(sessionID);
  const table = tableError ? [tableError] : [];
  if (!s) return table.map((text) => ({ type: "text", text }));
  const once = s.once.splice(0);
  const errors = s.errors.splice(0);
  return [...table, ...s.start, ...s.turn, ...once, ...errors].map((text) => ({ type: "text", text }));
}

/**
 * Hand a hook result to the next request. opencode cannot continue a finished turn or a subagent
 * call, so a reminder or a block from a Stop, subagent, or bus-event hook waits for the next request.
 */
function deliverLater(sessionID, out) {
  const s = sessions.get(sessionID);
  // A hook result for a session that was never started, or that already ended, has no request to reach.
  if (!s) {
    for (const text of [...out.context, ...(out.block ? [out.block] : []), ...out.errors]) console.error(text);
    return;
  }
  s.once.push(...out.context);
  if (out.block) s.once.push(out.block);
  s.errors.push(...out.errors);
}

/** The Claude payload fields of a `subagent` call. opencode names the agent `agent`, not `subagent_type`. */
function subagentFields(input) {
  return { agent_type: input.agent, description: input.description, prompt: input.prompt };
}

/** The model text llmenv reads, `provider/model#variant`, from an opencode model reference. */
function modelText(ref) {
  return `${ref.providerID}/${ref.id}${ref.variant ? `#${ref.variant}` : ""}`;
}

/**
 * Claude hook events that opencode raises as bus events: the Claude event name and its payload.
 * `session.step.ended` is the closest boundary to PostToolBatch, not the same one: it ends each
 * model step, including a step with no tool call.
 */
const BUS_HOOKS = {
  "permission.asked": (d) => ({
    event: "Notification",
    payload: { message: d.message ?? `Permission needed for ${d.action}: ${d.resources.join(", ")}` },
  }),
  "session.compaction.started": (d) => ({ event: "PreCompact", payload: { trigger: d.reason }, subject: d.reason }),
  "session.model.selected": (d) => ({
    event: "PostModelSwitch",
    payload: { ...(d.previous ? { from_model: modelText(d.previous) } : {}), to_model: modelText(d.model) },
  }),
  "session.step.ended": () => ({ event: "PostToolBatch", payload: {} }),
};

async function onEvent(ev) {
  const sessionID = ev?.data?.sessionID;
  if (!sessionID) return;
  if (ev.type === "session.created") await startSession(sessionID);
  else if (ev.type === "session.execution.succeeded") {
    deliverLater(sessionID, await runHooks("Stop", sessionID, { stop_hook_active: false }));
  } else if (ev.type === "session.deleted") await endSession(sessionID);
  // A plain object inherits `constructor` and friends, so only an own key names a bus hook.
  else if (Object.hasOwn(BUS_HOOKS, ev.type)) {
    const { event, payload, subject } = BUS_HOOKS[ev.type](ev.data);
    deliverLater(sessionID, await runHooks(event, sessionID, payload, subject));
  }
}

/** Log `text`, and give it to the next request of every open session. */
function toEverySession(text) {
  console.error(text);
  for (const s of sessions.values()) s.errors.push(text);
}

export default {
  id: "llmenv",
  setup: async (ctx) => {
    if (ctx.location?.directory) workDir = ctx.location.directory;
    await ctx.tool.hook("execute.before", async (e) => {
      // Without a usable hook table no gate runs, so a tool call is refused with the reason
      // rather than run unguarded.
      if (tableError) throw new Error(tableError);
      await startSession(e.sessionID);
      const neutral = toNeutral(e.tool, e.input ?? {});
      const out = await runHooks("PreToolUse", e.sessionID, { tool_name: neutral.name, tool_input: neutral.input }, neutral.name);
      state(e.sessionID).errors.push(...out.errors);
      if (out.block) throw new Error(out.block);
      if (out.updatedInput) e.input = fromNeutral(e.tool, out.updatedInput);
      if (out.context.length) state(e.sessionID).turn.push(...out.context);
      if (e.tool === "subagent") {
        // A block stops the launch, as a PreToolUse block does. The other output still reaches the model.
        const { block, ...rest } = await runHooks("SubagentStart", e.sessionID, subagentFields(e.input ?? {}), e.input?.agent);
        deliverLater(e.sessionID, rest);
        if (block) throw new Error(block);
      }
    });
    await ctx.tool.hook("execute.after", async (e) => {
      const neutral = toNeutral(e.tool, e.input ?? {});
      // Claude Code sends a failed call to PostToolUseFailure, not to PostToolUse.
      const failed = e.status !== "completed";
      const response = failed ? { error: String(e.error?.message ?? e.error ?? "unknown error") } : e.result;
      const event = failed ? "PostToolUseFailure" : "PostToolUse";
      const payload = { tool_name: neutral.name, tool_input: neutral.input, tool_response: response };
      // The failure consumer reads the top-level error, as Claude Code sends it.
      if (failed) payload.error = response.error;
      const out = await runHooks(event, e.sessionID, payload, neutral.name);
      const s = state(e.sessionID);
      queueOutcome(s, out);
      if (out.context.length) s.turn.push(...out.context);
      // The subagent's own Output is `result.output`. A background call returns "running" there at
      // launch, so its stop is not reported here (see docs/reference/opencode-v2-parity.md).
      const run = e.tool === "subagent" && e.status === "completed" ? e.result?.output : undefined;
      if (run?.status === "completed") {
        const stop = { stop_hook_active: false, ...subagentFields(e.input ?? {}), last_assistant_message: run.output };
        deliverLater(e.sessionID, await runHooks("SubagentStop", e.sessionID, stop, e.input?.agent));
      }
    });
    await ctx.session.hook("prompt", async (e) => {
      await startSession(e.sessionID);
      const out = await runHooks("UserPromptSubmit", e.sessionID, { prompt: e.prompt?.text ?? "" });
      const s = state(e.sessionID);
      s.turn = out.context;
      s.errors.push(...out.errors);
      if (out.block) throw new Error(out.block);
    });
    await ctx.session.hook("context", async (e) => {
      e.system.push(...systemParts(e.sessionID));
    });
    // Not awaited: setup must return, and the event stream never ends.
    void (async () => {
      for await (const ev of ctx.event.subscribe()) {
        await onEvent(ev).catch((err) => toEverySession(`llmenv: the ${ev.type} event hook failed: ${err?.message ?? err}`));
      }
    })().catch((err) => toEverySession(`llmenv: the event stream stopped, so SessionStart, Stop, SessionEnd, Notification, PreCompact, PostModelSwitch, and PostToolBatch hooks no longer run: ${err?.message ?? err}`));
    return async () => {
      await Promise.all([...sessions.keys()].map(endSession));
    };
  },
};
